DECLARE @Anul INT = select distinct an from app.Salariat;
DECLARE @Luna INT = select distinct luna from app.Salariat;

;WITH Zile AS (
    SELECT DATEFROMPARTS(@Anul, @Luna, 1) AS Data
    UNION ALL
    SELECT DATEADD(DAY, 1, Data)
    FROM Zile
    WHERE MONTH(DATEADD(DAY, 1, Data)) = @Luna
)
SELECT COUNT(*) AS ZileLucratoare
FROM Zile
WHERE DATENAME(WEEKDAY, Data) NOT IN ('Saturday', 'Sunday');
